<script setup>
import { computed, onMounted, reactive, ref } from 'vue';
import { Home, Plus, UserPlus, UsersRound } from 'lucide-vue-next';
import api, { apiError } from '../services/api';
import { useAuthStore } from '../stores/auth';
const emit = defineEmits(['selected']); const auth = useAuthStore();
// Families are an administrative area; the whole panel needs settings.manage.
const canManage = computed(() => auth.canArea('households', 'manage'));
// Only a super admin may create additional family workspaces; everyone else is
// scoped to their own family, so the API only ever returns that one card.
const canCreateFamily = computed(() => auth.isSuperAdmin);
// Only a super admin may grant super-admin, so hide it from everyone else.
const assignableRoles = computed(() => roles.value.filter((role) => auth.isSuperAdmin || role.name !== 'super-admin'));
const households = ref([]); const selected = ref(null); const members = ref([]); const roles = ref([]); const loading = ref(true); const saving = ref(false); const error = ref(''); const notice = ref(''); const family = reactive({ name: '', timezone: 'Asia/Kolkata', currency: 'INR', address: '' }); const member = reactive({ name: '', email: '', phone: '', password: '', role: 'family-member', relationship: 'Family member' });
const label = (value) => String(value || '').replaceAll('-', ' ').replace(/\b\w/g, (c) => c.toUpperCase());
const loadMembers = async (id) => { if (!id) return; members.value = (await api.get(`/households/${id}/users`)).data.data; };
const load = async () => { loading.value = true; try { const [familyResponse, access] = await Promise.all([api.get('/households'), api.get('/settings/access')]); households.value = familyResponse.data.data; roles.value = access.data.roles; selected.value = households.value[0] || null; await loadMembers(selected.value?.id); if (selected.value) emit('selected', selected.value); } catch (e) { error.value = apiError(e); } finally { loading.value = false; } };
const select = async (item) => { selected.value = item; await loadMembers(item.id); emit('selected', item); };
const createFamily = async () => { saving.value = true; error.value = ''; try { const response = (await api.post('/households', family)).data; Object.assign(family, { name: '', timezone: 'Asia/Kolkata', currency: 'INR', address: '' }); households.value.push(response.household); selected.value = response.household; members.value = []; emit('selected', response.household); notice.value = 'Family created. Add its members and properties.'; } catch (e) { error.value = apiError(e); } finally { saving.value = false; } };
const addMember = async () => { if (!selected.value) return; saving.value = true; error.value = ''; try { await api.post(`/households/${selected.value.id}/users`, member); Object.assign(member, { name: '', email: '', phone: '', password: '', role: 'family-member', relationship: 'Family member' }); await loadMembers(selected.value.id); notice.value = 'Family member added.'; } catch (e) { error.value = apiError(e); } finally { saving.value = false; } };
onMounted(load);
</script>
<template><div class="space-y-4"><div><p class="eyebrow flex items-center gap-2"><Home :size="13" /> Families & properties</p><h2 class="mt-1 text-xl font-semibold">Multiple family workspaces</h2><p class="mt-1 text-xs text-[#719b8e]">Each family has its own members, properties, expenses, bills, tasks, and dashboard data.{{ canCreateFamily ? ' You can switch between and create any family workspace.' : ' You can only see and manage your own family.' }}</p></div><p v-if="error" class="rounded-xl bg-rose-400/10 px-3 py-2 text-xs text-rose-200">{{ error }}</p><p v-if="notice" class="rounded-xl bg-emerald-300/10 px-3 py-2 text-xs text-emerald-100">{{ notice }}</p><div v-if="loading" class="h-32 rounded-2xl skeleton"></div><template v-else><div class="grid gap-3 sm:grid-cols-2 lg:grid-cols-3"><button v-for="item in households" :key="item.id" class="rounded-2xl border p-4 text-left transition" :class="selected?.id === item.id ? 'border-emerald-200/50 bg-emerald-200/10' : 'border-emerald-100/10 bg-[#082b27]'" @click="select(item)"><div class="flex items-center gap-2"><span class="flex h-8 w-8 items-center justify-center rounded-lg bg-emerald-300/10 text-emerald-200"><Home :size="15" /></span><p class="text-sm font-semibold text-white">{{ item.name }}</p></div><p class="mt-3 text-[10px] text-[#7fa99c]">{{ item.users_count }} members · {{ item.properties_count }} properties</p><p class="mt-1 text-[10px] text-[#5f8b80]">{{ item.timezone }} · {{ item.currency }}</p></button></div><div class="grid gap-4 lg:grid-cols-2"><form v-if="canCreateFamily" class="rounded-2xl border border-emerald-100/10 bg-[#082b27] p-4" @submit.prevent="createFamily"><p class="text-sm font-semibold text-white">Create a family</p><div class="mt-3 grid gap-2 sm:grid-cols-2"><input v-model="family.name" class="field sm:col-span-2" placeholder="Family name" required/><select v-model="family.timezone" class="field"><option>Asia/Kolkata</option><option>UTC</option><option>Asia/Dubai</option><option>Europe/London</option></select><select v-model="family.currency" class="field"><option>INR</option><option>USD</option><option>EUR</option><option>AED</option></select><input v-model="family.address" class="field sm:col-span-2" placeholder="Address"/></div><button class="btn-primary mt-3" :disabled="saving"><Plus :size="15" /> Create family</button></form><form v-if="canManage" class="rounded-2xl border border-emerald-100/10 bg-[#082b27] p-4" @submit.prevent="addMember"><p class="text-sm font-semibold text-white">Add member to {{ selected?.name || 'family' }}</p><div class="mt-3 grid gap-2 sm:grid-cols-2"><input v-model="member.name" class="field" placeholder="Full name" required/><input v-model="member.email" class="field" type="email" placeholder="Email" required/><input v-model="member.phone" class="field" placeholder="Mobile"/><input v-model="member.password" class="field" type="password" minlength="8" placeholder="Temporary password" required/><select v-model="member.role" class="field"><option v-for="role in assignableRoles" :key="role.id" :value="role.name">{{ label(role.name) }}</option></select><input v-model="member.relationship" class="field" placeholder="Relationship"/></div><button class="btn-primary mt-3" :disabled="saving || !selected"><UserPlus :size="15" /> Add member</button></form></div><div v-if="selected" class="rounded-2xl border border-emerald-100/10 p-4"><div class="flex items-center gap-2"><UsersRound :size="16" class="text-emerald-200"/><p class="text-sm font-semibold">{{ selected.name }} members</p></div><div class="mt-3 grid gap-2 sm:grid-cols-2 lg:grid-cols-3"><div v-for="person in members" :key="person.id" class="rounded-xl bg-[#082b27] p-3"><p class="text-xs font-semibold text-white">{{ person.name }}</p><p class="mt-1 text-[10px] text-[#7fa99c]">{{ person.email }}</p><p class="mt-1 text-[10px] text-emerald-200/70">{{ label(person.roles?.[0]?.name) }}</p></div></div></div></template></div></template>
